#include "kernel_operator.h"

class KernelMhcPreBlock {
public:
    __aicore__ inline KernelMhcPreBlock() {}

    __aicore__ inline void Init(GM_ADDR residual,
                               GM_ADDR fn,
                               GM_ADDR hc_scale,
                               GM_ADDR hc_base,
                               GM_ADDR post_mix,
                               GM_ADDR comb_mix,
                               GM_ADDR layer_input,
                               uint32_t totalResidual,
                               uint32_t totalFn,
                               uint32_t totalScale,
                               uint32_t totalBase,
                               uint32_t N,
                               uint32_t hc,
                               uint32_t H,
                               uint32_t dFlat,
                               uint32_t hc2,
                               uint32_t hc3,
                               uint32_t blockTokens,
                               float invDFlat,
                               float rmsEps,
                               float hcPreEps,
                               float hcSinkhornEps,
                               float hcPostMultValue,
                               uint32_t sinkhornRepeat)
    {
        (void)totalFn; (void)totalScale; (void)totalBase;
        this->totalResidual = totalResidual;

        this->N = N;
        this->hc = hc;
        this->H = H;
        this->dFlat = dFlat;
        this->hc2 = hc2;
        this->hc3 = hc3;
        this->blockTokens = blockTokens;

        this->invDFlat = invDFlat;
        this->rmsEps = rmsEps;
        this->hcPreEps = hcPreEps;
        this->hcSinkhornEps = hcSinkhornEps;
        this->hcPostMultValue = hcPostMultValue;
        this->sinkhornRepeat = sinkhornRepeat;

        residualGm.SetGlobalBuffer((__gm__ float*)residual, totalResidual);         // [N,hc,H]
        fnGm.SetGlobalBuffer((__gm__ float*)fn, (uint64_t)hc3 * (uint64_t)dFlat);  // [hc3,dFlat]
        scaleGm.SetGlobalBuffer((__gm__ float*)hc_scale, 3);                       // [3]
        baseGm.SetGlobalBuffer((__gm__ float*)hc_base, hc3);                       // [hc3]

        postGm.SetGlobalBuffer((__gm__ float*)post_mix, (uint64_t)N * (uint64_t)hc);       // [N,hc,1] flattened
        combGm.SetGlobalBuffer((__gm__ float*)comb_mix, (uint64_t)N * (uint64_t)hc2);      // [N,hc,hc]
        outGm.SetGlobalBuffer((__gm__ float*)layer_input, (uint64_t)N * (uint64_t)H);      // [N,H]

        pipe.InitBuffer(residualQueue, 1, 81920u);
        pipe.InitBuffer(fnQueue, 1, 40960u);
        pipe.InitBuffer(productBuf, 40960u);
        pipe.InitBuffer(reduceBuf, 22016u);
        pipe.InitBuffer(layerOutQueue, 1, 10240u);
        pipe.InitBuffer(smallOutQueue, 1, 96u);
        pipe.InitBuffer(scaleBaseQueue, 1, 128u);
    }

    __aicore__ inline void Process()
    {
        const uint32_t bid = (uint32_t)AscendC::GetBlockIdx();
        if (N == 0u || hc == 0u || H == 0u) return;

        const uint32_t nStart = bid * blockTokens;
        if (nStart >= N) return;
        uint32_t nEnd = nStart + blockTokens;
        if (nEnd > N) nEnd = N;

        if (hc != 4u || hc3 != 24u || H != 2560u || dFlat != 10240u) {
            for (uint32_t n = nStart; n < nEnd; ++n) WriteZerosToken(n);
            return;
        }

        AscendC::LocalTensor<float> scaleBaseLocal = scaleBaseQueue.AllocTensor<float>();
        AscendC::DataCopyExtParams scaleCopy{1u, 12u, 0u, 0u, 0u};
        AscendC::DataCopyPadExtParams<float> noPad{false, 0u, 0u, 0.0f};
        AscendC::DataCopyPad(scaleBaseLocal, scaleGm, scaleCopy, noPad);
        AscendC::DataCopy(scaleBaseLocal[8], baseGm, 24u);
        scaleBaseQueue.EnQue(scaleBaseLocal);
        scaleBaseLocal = scaleBaseQueue.DeQue<float>();

        for (uint32_t batchStart = nStart; batchStart < nEnd; batchStart += 2u) {
            const uint32_t batchCount = ((batchStart + 1u) < nEnd) ? 2u : 1u;
            AscendC::LocalTensor<float> residualLocal = residualQueue.AllocTensor<float>();
            AscendC::DataCopy(residualLocal, residualGm[(uint64_t)batchStart * (uint64_t)dFlat],
                              batchCount * dFlat);
            residualQueue.EnQue(residualLocal);
            residualLocal = residualQueue.DeQue<float>();

            float rmsInv[2] = {0.0f, 0.0f};
            float mixes[2][24];
            for (uint32_t t = 0u; t < batchCount; ++t) {
                rmsInv[t] = ResidualRmsInv(residualLocal[t * dFlat]);
            }

            for (uint32_t k = 0u; k < 24u; ++k) {
                AscendC::LocalTensor<float> fnLocal = fnQueue.AllocTensor<float>();
                AscendC::DataCopy(fnLocal, fnGm[(uint64_t)k * (uint64_t)dFlat], dFlat);
                fnQueue.EnQue(fnLocal);
                fnLocal = fnQueue.DeQue<float>();
                for (uint32_t t = 0u; t < batchCount; ++t) {
                    const float dot = DotResidualFnRowHc4(residualLocal[t * dFlat], fnLocal);
                    const float scale = scaleBaseLocal.GetValue((k < 4u) ? 0u : ((k < 8u) ? 1u : 2u));
                    const float base = scaleBaseLocal.GetValue(8u + k);
                    mixes[t][k] = dot * rmsInv[t] * scale + base;
                }
                fnQueue.FreeTensor(fnLocal);
            }

            for (uint32_t t = 0u; t < batchCount; ++t) {
                ProcessTokenHc4_FusedSqsumLayer(batchStart + t, residualLocal[t * dFlat], mixes[t]);
            }
            residualQueue.FreeTensor(residualLocal);
        }
        scaleBaseQueue.FreeTensor(scaleBaseLocal);
    }

private:
    __aicore__ inline void WriteZerosToken(uint32_t n)
    {
        const uint64_t H64 = (uint64_t)H;
        const uint64_t hc64 = (uint64_t)hc;
        const uint64_t basePost = (uint64_t)n * hc64;
        for (uint32_t j = 0; j < hc; ++j) postGm.SetValue(basePost + (uint64_t)j, 0.0f);

        const uint64_t baseComb = (uint64_t)n * hc64 * hc64;
        for (uint32_t t = 0; t < hc*hc; ++t) combGm.SetValue(baseComb + (uint64_t)t, 0.0f);

        const uint64_t baseOut = (uint64_t)n * H64;
        for (uint32_t h = 0; h < H; ++h) outGm.SetValue(baseOut + (uint64_t)h, 0.0f);
    }

    __aicore__ inline float ClampF(float x, float lo, float hi)
    {
        if (x < lo) return lo;
        if (x > hi) return hi;
        return x;
    }

    __aicore__ inline float ExpApprox(float x)
    {
        x = ClampF(x, -10.0f, 10.0f);
        float x2 = x * x;
        float x3 = x2 * x;
        float x4 = x2 * x2;
        float x5 = x4 * x;
        return 1.0f + x + 0.5f * x2 + (1.0f / 6.0f) * x3 + (1.0f / 24.0f) * x4 + (1.0f / 120.0f) * x5;
    }

    __aicore__ inline float Sigmoid(float x)
    {
        x = ClampF(x, -8.0f, 8.0f);
        float e = ExpApprox(-x);
        return 1.0f / (1.0f + e);
    }

    __aicore__ inline float RsqrtNewton(float x)
    {
        if (x <= 0.0f) return 0.0f;
        float y = 1.0f / x;
        for (int it = 0; it < 6; ++it) {
            y = y * (1.5f - 0.5f * x * y * y);
        }
        return y;
    }

    __aicore__ inline float ReduceLocal(const AscendC::LocalTensor<float>& src, uint32_t count)
    {
        AscendC::LocalTensor<float> reduceLocal = reduceBuf.Get<float>();
        AscendC::ReduceSum(reduceLocal, src, reduceLocal[8], static_cast<int32_t>(count));
        event_t eventId = static_cast<event_t>(pipe.FetchEventID(AscendC::HardEvent::V_S));
        AscendC::SetFlag<AscendC::HardEvent::V_S>(eventId);
        AscendC::WaitFlag<AscendC::HardEvent::V_S>(eventId);
        return reduceLocal.GetValue(0u);
    }

    __aicore__ inline float ResidualRmsInv(const AscendC::LocalTensor<float>& residualLocal)
    {
        AscendC::LocalTensor<float> productLocal = productBuf.Get<float>();
        AscendC::Mul(productLocal, residualLocal, residualLocal, static_cast<int32_t>(dFlat));
        const float sumsq = ReduceLocal(productLocal, dFlat);
        return RsqrtNewton(sumsq * invDFlat + rmsEps);
    }

    __aicore__ inline float DotResidualFnRowHc4(const AscendC::LocalTensor<float>& residualLocal,
                                                const AscendC::LocalTensor<float>& fnLocal)
    {
        AscendC::LocalTensor<float> productLocal = productBuf.Get<float>();
        AscendC::Mul(productLocal, residualLocal, fnLocal, static_cast<int32_t>(dFlat));
        return ReduceLocal(productLocal, dFlat);
    }

    __aicore__ inline void SoftmaxRow4(float *row)
    {
        float mx = row[0];
        if (row[1] > mx) mx = row[1];
        if (row[2] > mx) mx = row[2];
        if (row[3] > mx) mx = row[3];

        float e0 = ExpApprox(row[0] - mx);
        float e1 = ExpApprox(row[1] - mx);
        float e2 = ExpApprox(row[2] - mx);
        float e3 = ExpApprox(row[3] - mx);

        float sum = e0 + e1 + e2 + e3;
        float inv = 1.0f / (sum + 1e-20f);

        row[0] = e0 * inv;
        row[1] = e1 * inv;
        row[2] = e2 * inv;
        row[3] = e3 * inv;
    }

    __aicore__ inline void Sinkhorn4(float *m)
    {
        uint32_t repeat = sinkhornRepeat;
        if (repeat == 0u) repeat = 1u;

        SoftmaxRow4(m + 0);
        SoftmaxRow4(m + 4);
        SoftmaxRow4(m + 8);
        SoftmaxRow4(m + 12);
        for (uint32_t i = 0u; i < 16u; ++i) m[i] += hcSinkhornEps;

        for (uint32_t c = 0u; c < 4u; ++c) {
            float s = m[0*4+c] + m[1*4+c] + m[2*4+c] + m[3*4+c];
            float inv = 1.0f / (s + hcSinkhornEps);
            m[0*4+c] *= inv; m[1*4+c] *= inv; m[2*4+c] *= inv; m[3*4+c] *= inv;
        }

        for (uint32_t it = 1u; it < repeat; ++it) {
            for (uint32_t r = 0u; r < 4u; ++r) {
                float s = m[r*4+0] + m[r*4+1] + m[r*4+2] + m[r*4+3];
                float inv = 1.0f / (s + hcSinkhornEps);
                m[r*4+0] *= inv; m[r*4+1] *= inv; m[r*4+2] *= inv; m[r*4+3] *= inv;
            }
            for (uint32_t c = 0u; c < 4u; ++c) {
                float s = m[0*4+c] + m[1*4+c] + m[2*4+c] + m[3*4+c];
                float inv = 1.0f / (s + hcSinkhornEps);
                m[0*4+c] *= inv; m[1*4+c] *= inv; m[2*4+c] *= inv; m[3*4+c] *= inv;
            }
        }
    }

    __aicore__ inline void ProcessTokenHc4_FusedSqsumLayer(
        uint32_t n, const AscendC::LocalTensor<float>& residualLocal, float *mixes)
    {
        float pre0 = Sigmoid(mixes[0]) + hcPreEps;
        float pre1 = Sigmoid(mixes[1]) + hcPreEps;
        float pre2 = Sigmoid(mixes[2]) + hcPreEps;
        float pre3 = Sigmoid(mixes[3]) + hcPreEps;

        AscendC::LocalTensor<float> smallLocal = smallOutQueue.AllocTensor<float>();
        smallLocal.SetValue(0u, Sigmoid(mixes[4]) * hcPostMultValue);
        smallLocal.SetValue(1u, Sigmoid(mixes[5]) * hcPostMultValue);
        smallLocal.SetValue(2u, Sigmoid(mixes[6]) * hcPostMultValue);
        smallLocal.SetValue(3u, Sigmoid(mixes[7]) * hcPostMultValue);
        float mat[16];
        #pragma unroll
        for (uint32_t i = 0u; i < 16u; ++i) mat[i] = mixes[8u + i];
        Sinkhorn4(mat);
        #pragma unroll
        for (uint32_t i = 0u; i < 16u; ++i) smallLocal.SetValue(8u + i, mat[i]);
        smallOutQueue.EnQue(smallLocal);
        smallLocal = smallOutQueue.DeQue<float>();
        event_t scalarOutEvent = static_cast<event_t>(pipe.FetchEventID(AscendC::HardEvent::S_MTE3));
        AscendC::SetFlag<AscendC::HardEvent::S_MTE3>(scalarOutEvent);
        AscendC::WaitFlag<AscendC::HardEvent::S_MTE3>(scalarOutEvent);
        AscendC::DataCopyExtParams postCopy{1u, 16u, 0u, 0u, 0u};
        AscendC::DataCopyPad(postGm[(uint64_t)n * 4ull], smallLocal, postCopy);
        AscendC::DataCopy(combGm[(uint64_t)n * 16ull], smallLocal[8], 16u);
        smallOutQueue.FreeTensor(smallLocal);

        AscendC::LocalTensor<float> layerLocal = layerOutQueue.AllocTensor<float>();
        AscendC::Muls(layerLocal, residualLocal, pre0, static_cast<int32_t>(H));
        AscendC::Muls(productBuf.Get<float>(), residualLocal[H], pre1, static_cast<int32_t>(H));
        AscendC::Add(layerLocal, layerLocal, productBuf.Get<float>(), static_cast<int32_t>(H));
        AscendC::Muls(productBuf.Get<float>(), residualLocal[2u * H], pre2, static_cast<int32_t>(H));
        AscendC::Add(layerLocal, layerLocal, productBuf.Get<float>(), static_cast<int32_t>(H));
        AscendC::Muls(productBuf.Get<float>(), residualLocal[3u * H], pre3, static_cast<int32_t>(H));
        AscendC::Add(layerLocal, layerLocal, productBuf.Get<float>(), static_cast<int32_t>(H));
        layerOutQueue.EnQue(layerLocal);
        layerLocal = layerOutQueue.DeQue<float>();
        AscendC::DataCopy(outGm[(uint64_t)n * (uint64_t)H], layerLocal, H);
        layerOutQueue.FreeTensor(layerLocal);
    }

private:
    AscendC::GlobalTensor<float> residualGm;
    AscendC::GlobalTensor<float> fnGm;
    AscendC::GlobalTensor<float> scaleGm;
    AscendC::GlobalTensor<float> baseGm;

    AscendC::GlobalTensor<float> postGm;
    AscendC::GlobalTensor<float> combGm;
    AscendC::GlobalTensor<float> outGm;

    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> residualQueue;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> fnQueue;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> scaleBaseQueue;
    AscendC::TBuf<AscendC::TPosition::VECCALC> productBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> layerOutQueue;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> smallOutQueue;

    uint32_t totalResidual;
    uint32_t N, hc, H, dFlat, hc2, hc3;
    uint32_t blockTokens;

    float invDFlat, rmsEps, hcPreEps, hcSinkhornEps, hcPostMultValue;
    uint32_t sinkhornRepeat;
};

extern "C" __global__ __aicore__ void mhc_pre_block_custom(GM_ADDR residual,
