#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

class KernelStreamWriteCustom {
public:
    __aicore__ inline KernelStreamWriteCustom() {}

    __aicore__ inline void Init(GM_ADDR y, GM_ADDR h, GM_ADDR out,
                               uint32_t B, uint32_t T, uint32_t N, uint32_t C,
                               uint32_t BT, uint32_t tileC, uint32_t totalTasks,
                               uint32_t outputTileElems, uint32_t hValidElems,
                               uint32_t hStorageElems)
    {
        this->B = B;
        this->T = T;
        this->N = N;
        this->C = C;
        this->BT = BT;
        this->tileC = tileC;
        this->totalTasks = totalTasks;
        this->outputTileElems = outputTileElems;
        this->hValidElems = hValidElems;
        this->hStorageElems = hStorageElems;

        yGm.SetGlobalBuffer((__gm__ DTYPE_Y*)y, BT * C);
        hGm.SetGlobalBuffer((__gm__ DTYPE_H_POST*)h, BT * N);
        outGm.SetGlobalBuffer((__gm__ DTYPE_OUT*)out, BT * N * C);

        pipe.InitBuffer(yQueue, BUFFER_NUM, this->tileC * sizeof(DTYPE_Y));
        pipe.InitBuffer(oQueue, BUFFER_NUM, this->outputTileElems * sizeof(DTYPE_OUT));
        pipe.InitBuffer(hQueue, 1, this->hStorageElems * sizeof(DTYPE_H_POST));
    }

    __aicore__ inline void Process()
    {
        const uint32_t blockIdx = AscendC::GetBlockIdx();
        const uint32_t blockNum = AscendC::GetBlockNum();

        for (uint32_t bt = blockIdx; bt < totalTasks; bt += blockNum) {
            AscendC::LocalTensor<DTYPE_H_POST> hLocal = hQueue.AllocTensor<DTYPE_H_POST>();
            const uint32_t hCopyBytes = hValidElems * static_cast<uint32_t>(sizeof(DTYPE_H_POST));
            const AscendC::DataCopyExtParams hCopyParams{1, hCopyBytes, 0, 0, 0};
            const AscendC::DataCopyPadExtParams<DTYPE_H_POST> hPadParams{false, 0, 0, 0};
            AscendC::DataCopyPad(hLocal, hGm[bt * N], hCopyParams, hPadParams);
            hQueue.EnQue(hLocal);

            CopyInY(bt);
            ComputeAndStoreAllN(bt);
        }
    }

private:
    __aicore__ inline void CopyInY(uint32_t bt)
    {
        AscendC::LocalTensor<DTYPE_Y> yLocal = yQueue.AllocTensor<DTYPE_Y>();
        AscendC::DataCopy(yLocal, yGm[bt * C], tileC);
        yQueue.EnQue(yLocal);
    }

    __aicore__ inline void ComputeAndStoreAllN(uint32_t bt)
    {
        AscendC::LocalTensor<DTYPE_Y> yLocal = yQueue.DeQue<DTYPE_Y>();
        AscendC::LocalTensor<DTYPE_H_POST> hLocal = hQueue.DeQue<DTYPE_H_POST>();
        AscendC::LocalTensor<DTYPE_OUT> oLocal = oQueue.AllocTensor<DTYPE_OUT>();

        for (uint32_t n = 0; n < N; ++n) {
            const DTYPE_OUT hv = (DTYPE_OUT)hLocal.GetValue(n);
            AscendC::Muls(oLocal[n * tileC], yLocal, hv, tileC);
        }

        yQueue.FreeTensor(yLocal);
        hQueue.FreeTensor(hLocal);
        oQueue.EnQue(oLocal);
        CopyOut(bt);
    }

    __aicore__ inline void CopyOut(uint32_t bt)
    {
        AscendC::LocalTensor<DTYPE_OUT> oLocal = oQueue.DeQue<DTYPE_OUT>();
        AscendC::DataCopy(outGm[bt * outputTileElems], oLocal, outputTileElems);
        oQueue.FreeTensor(oLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> yQueue;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> hQueue;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> oQueue;

    AscendC::GlobalTensor<DTYPE_Y> yGm;
    AscendC::GlobalTensor<DTYPE_H_POST> hGm;
    AscendC::GlobalTensor<DTYPE_OUT> outGm;

    uint32_t B, T, N, C;
    uint32_t BT, tileC, totalTasks, outputTileElems, hValidElems, hStorageElems;
};

extern "C" __global__ __aicore__ void stream_write_custom(GM_ADDR y, GM_ADDR h_post, GM_ADDR out,
                                                         GM_ADDR workspace, GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(tiling_data, tiling);
    KernelStreamWriteCustom op;
    op.Init(y, h_post, out,
            tiling_data.B, tiling_data.T, tiling_data.N, tiling_data.C,
            tiling_data.BT, tiling_data.tileC, tiling_data.totalTasks,
            tiling_data.outputTileElems, tiling_data.hValidElems,
            tiling_data.hStorageElems);
    op.Process();
}
